insert ignore into INFRA_INTERFACE_VO_CLASS(CREATOR_ID, UPDATER_ID, ID, NAME, COMMENT, PARENT_ID) values('1', '1', '0a6a946a-49af-42bc-b06d-329d8be89a06', 'InfraNoBase', '编号管理', '64d538ec-3b21-4d17-81e0-36861fd066f3');
DROP TABLE IF EXISTS `infra_no`;
CREATE TABLE `infra_no` (
  `id` VARCHAR(50) NOT NULL COMMENT '编号',
  `key_name` VARCHAR(50) NOT NULL COMMENT '编码名称',
  `prefix` VARCHAR(50) NOT NULL COMMENT '前缀',
  `date_form` INT(11) NOT NULL DEFAULT 0 COMMENT '日期格式',
  `date_base` INT(11) NOT NULL DEFAULT 0 COMMENT '日期计算方式',
  `last_date` DATE NOT NULL COMMENT '最后日期',
  `postfix_len` INT(11) NOT NULL DEFAULT 0 COMMENT '后缀长度',
  `postfix_val` INT(11) NOT NULL DEFAULT 0 COMMENT '后缀值',
  `create_time` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator_id` BIGINT NOT NULL DEFAULT 0 COMMENT '创建人ID',
  `updater_id` BIGINT NOT NULL DEFAULT 0 COMMENT '修改人ID',
  `deleted` TINYINT(4) NOT NULL DEFAULT 0 COMMENT '是否删除',
  UNIQUE INDEX `UN_infra_no_key_name` (`key_name`),
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '编号管理';
